// The product's accessibility conformance report — VPAT® 2.5 INT (#2037).
//
// ONE SOURCE. These rows are rendered three ways — the public page
// /accessibility/vpat, the Markdown served at /accessibility/vpat.md and the
// committed docs/legal/vpat.md — by src/lib/vpatRender.ts, and
// scripts/vpat-evidence.mjs regenerates the files from them. A row that is
// edited here and not regenerated fails scripts/test/vpat.test.mjs.
//
// THE RULE EVERY ROW OBEYS: `Supports` is never asserted without an evidence
// path — a spec file, a source file whose behaviour is the claim, a baseline
// entry, or a repeatable `check:` command. "It looks fine" is `Partially
// Supports` with the manual test named as pending. The unit test enforces the
// shape (a `Supports` row with an empty `evidence` list is red, and every path
// must exist in the tree); only a human can enforce the honesty of the remark.
//
// Markdown files are not shipped in the image (.dockerignore excludes *.md), so
// nothing here reads a file at runtime; the automated evidence the report cites
// is the generated src/lib/vpatEvidence.generated.ts.
//
// English only, on purpose: the criteria names and the four conformance terms
// are defined in English by the VPAT template, and a procurement reviewer
// compares this against other vendors' reports in that form. The page chrome
// around it is translated; the report is not.

export type Conformance = 'Supports' | 'Partially Supports' | 'Does Not Support' | 'Not Applicable';
export const CONFORMANCE_LEVELS: readonly Conformance[] = ['Supports', 'Partially Supports', 'Does Not Support', 'Not Applicable'];

export type WcagLevel = 'A' | 'AA' | 'AAA';
export type WcagVersion = '2.0' | '2.1' | '2.2';

export interface VpatRow {
  /** "1.4.3", "9.1.1.1", "502.3.1" — printed as the criterion number. */
  id: string;
  name: string;
  /** WCAG rows only. */
  level?: WcagLevel;
  /** WCAG rows only: the version that introduced the criterion (EN 301 549 ch. 9 cites 2.1, Section 508 cites 2.0). */
  since?: WcagVersion;
  conformance: Conformance;
  remarks: string;
  /**
   * What makes the remark checkable: a repository path (optionally `:line`),
   * an issue (`#2864`) or a repeatable command (`check: …`). Required for
   * `Supports`; strongly expected everywhere else.
   */
  evidence: string[];
}

export interface VpatSection {
  /** "Chapter 4", "502" … */
  id: string;
  title: string;
  /** A one-paragraph note printed above the table (scope, "see WCAG", …). */
  note?: string;
  rows: VpatRow[];
}

/** The issue every "evidence pending" row points at, and the self-assessment story. */
export const VPAT_TRACKING_ISSUE = 2864;
export const VPAT_SELF_ASSESSMENT_ISSUE = 2033;

