/** The EN 301 549 clause 9 rows, generated from the WCAG rows (9.x.y.z ⇔ x.y.z, WCAG 2.1 A/AA only). */
export function enChapter9Rows(): VpatRow[] {
  return WCAG_ROWS.filter((r) => r.level !== 'AAA' && r.since !== '2.2').map((r) => ({
    ...r,
    id: `9.${r.id}`,
    remarks: `See WCAG ${r.id} ${r.name}.`,
  }));
}

export function wcagRows(level: WcagLevel): VpatRow[] {
  return WCAG_ROWS.filter((r) => r.level === level);
}

/** Is this evidence entry a repository path (as opposed to an issue or a command)? */
export function evidencePath(entry: string): string | null {
  if (/^#\d+$/.test(entry) || entry.startsWith('check:')) return null;
  return entry.replace(/:\d+$/, '');
}
